/* ESV passage bundle — every Scripture reference in the Statement of Faith.
 *
 * 91 passages, 441 verses, loaded only by /statement-of-faith so the
 * popup needs no network call and no API key at click time. Shared with the
 * Christ Community Church site, whose statement cites the same passages.
 *
 * Crossway permits quoting up to 500 verses of the ESV without written
 * permission. This file is deliberately held under that ceiling: 1 Corinthians
 * 12-14 (84 verses) is left out, so that reference renders as plain text on the
 * page instead of a button. Anything not in here degrades the same way, so a
 * reference the owner adds later is never broken — only unlinked.
 *
 * Shape: { "Book c:v-v": { b: "Book", v: [[chapter, verse, text], ...] } }
 * Keys use a plain hyphen for ranges; the server normalises en-dashes to match.
 */
window.TWC_SCRIPTURES={"1 Corinthians 11:26":{"b":"1 Corinthians","v":[[11,26,"For as often as you eat this bread and drink the cup, you proclaim the Lord's death until he comes."]]},"1 Corinthians 12:12-27":{"b":"1 Corinthians","v":[[12,12,"For just as the body is one and has many members, and all the members of the body, though many, are one body, so it is with Christ."],[12,13,"For in one Spirit we were all baptized into one body — Jews or Greeks, slaves or free — and all were made to drink of one Spirit."],[12,14,"For the body does not consist of one member but of many."],[12,15,"If the foot should say, “Because I am not a hand, I do not belong to the body,” that would not make it any less a part of the body."],[12,16,"And if the ear should say, “Because I am not an eye, I do not belong to the body,” that would not make it any less a part of the body."],[12,17,"If the whole body were an eye, where would be the sense of hearing? If the whole body were an ear, where would be the sense of smell?"],[12,18,"But as it is, God arranged the members in the body, each one of them, as he chose."],[12,19,"If all were a single member, where would the body be?"],[12,20,"As it is, there are many parts, yet one body."],[12,21,"The eye cannot say to the hand, “I have no need of you,” nor again the head to the feet, “I have no need of you.”"],[12,22,"On the contrary, the parts of the body that seem to be weaker are indispensable,"],[12,23,"and on those parts of the body that we think less honorable we bestow the greater honor, and our unpresentable parts are treated with greater modesty,"],[12,24,"which our more presentable parts do not require. But God has so composed the body, giving greater honor to the part that lacked it,"],[12,25,"that there may be no division in the body, but that the members may have the same care for one another."],[12,26,"If one member suffers, all suffer together; if one member is honored, all rejoice together."],[12,27,"Now you are the body of Christ and individually members of it."]]},"1 Corinthians 13:9-12":{"b":"1 Corinthians","v":[[13,9,"For we know in part and we prophesy in part,"],[13,10,"but when the perfect comes, the partial will pass away."],[13,11,"When I was a child, I spoke like a child, I thought like a child, I reasoned like a child. When I became a man, I gave up childish ways."],[13,12,"For now we see in a mirror dimly, but then face to face. Now I know in part; then I shall know fully, even as I have been fully known."]]},"1 Corinthians 15:3-8":{"b":"1 Corinthians","v":[[15,3,"For I delivered to you as of first importance what I also received: that Christ died for our sins in accordance with the Scriptures,"],[15,4,"that he was buried, that he was raised on the third day in accordance with the Scriptures,"],[15,5,"and that he appeared to Cephas, then to the twelve."],[15,6,"Then he appeared to more than five hundred brothers at one time, most of whom are still alive, though some have fallen asleep."],[15,7,"Then he appeared to James, then to all the apostles."],[15,8,"Last of all, as to one untimely born, he appeared also to me."]]},"1 Corinthians 6:18-20":{"b":"1 Corinthians","v":[[6,18,"Flee from sexual immorality. Every other sin a person commits is outside the body, but the sexually immoral person sins against his own body."],[6,19,"Or do you not know that your body is a temple of the Holy Spirit within you, whom you have from God? You are not your own,"],[6,20,"for you were bought with a price. So glorify God in your body."]]},"1 Corinthians 6:9-11":{"b":"1 Corinthians","v":[[6,9,"Or do you not know that the unrighteous will not inherit the kingdom of God? Do not be deceived: neither the sexually immoral, nor idolaters, nor adulterers, nor men who practice homosexuality,"],[6,10,"nor thieves, nor the greedy, nor drunkards, nor revilers, nor swindlers will inherit the kingdom of God."],[6,11,"And such were some of you. But you were washed, you were sanctified, you were justified in the name of the Lord Jesus Christ and by the Spirit of our God."]]},"1 Corinthians 8:4-6":{"b":"1 Corinthians","v":[[8,4,"Therefore, as to the eating of food offered to idols, we know that “an idol has no real existence,” and that “there is no God but one.”"],[8,5,"For although there may be so-called gods in heaven or on earth — as indeed there are many “gods” and many “lords” —"],[8,6,"yet for us there is one God, the Father, from whom are all things and for whom we exist, and one Lord, Jesus Christ, through whom are all things and through whom we exist."]]},"1 John 4:1-3":{"b":"1 John","v":[[4,1,"Beloved, do not believe every spirit, but test the spirits to see whether they are from God, for many false prophets have gone out into the world."],[4,2,"By this you know the Spirit of God: every spirit that confesses that Jesus Christ has come in the flesh is from God,"],[4,3,"and every spirit that does not confess Jesus is not from God. This is the spirit of the antichrist, which you heard was coming and now is in the world already."]]},"1 Peter 2:5-9":{"b":"1 Peter","v":[[2,5,"you yourselves like living stones are being built up as a spiritual house, to be a holy priesthood, to offer spiritual sacrifices acceptable to God through Jesus Christ."],[2,6,"For it stands in Scripture: “Behold, I am laying in Zion a stone, a cornerstone chosen and precious, and whoever believes in him will not be put to shame.”"],[2,7,"So the honor is for you who believe, but for those who do not believe, “The stone that the builders rejected has become the cornerstone,”"],[2,8,"and “A stone of stumbling, and a rock of offense.” They stumble because they disobey the word, as they were destined to do."],[2,9,"But you are a chosen race, a royal priesthood, a holy nation, a people for his own possession, that you may proclaim the excellencies of him who called you out of darkness into his marvelous light."]]},"1 Thessalonians 5:19-21":{"b":"1 Thessalonians","v":[[5,19,"Do not quench the Spirit."],[5,20,"Do not despise prophecies,"],[5,21,"but test everything; hold fast what is good."]]},"1 Timothy 2:11-14":{"b":"1 Timothy","v":[[2,11,"Let a woman learn quietly with all submissiveness."],[2,12,"I do not permit a woman to teach or to exercise authority over a man; rather, she is to remain quiet."],[2,13,"For Adam was formed first, then Eve;"],[2,14,"and Adam was not deceived, but the woman was deceived and became a transgressor."]]},"1 Timothy 3:1-8":{"b":"1 Timothy","v":[[3,1,"The saying is trustworthy: If anyone aspires to the office of overseer, he desires a noble task."],[3,2,"Therefore an overseer must be above reproach, the husband of one wife, sober-minded, self-controlled, respectable, hospitable, able to teach,"],[3,3,"not a drunkard, not violent but gentle, not quarrelsome, not a lover of money."],[3,4,"He must manage his own household well, with all dignity keeping his children submissive,"],[3,5,"for if someone does not know how to manage his own household, how will he care for God's church?"],[3,6,"He must not be a recent convert, or he may become puffed up with conceit and fall into the condemnation of the devil."],[3,7,"Moreover, he must be well thought of by outsiders, so that he may not fall into disgrace, into a snare of the devil."],[3,8,"Deacons likewise must be dignified, not double-tongued, not addicted to much wine, not greedy for dishonest gain."]]},"1 Timothy 5:19-22":{"b":"1 Timothy","v":[[5,19,"Do not admit a charge against an elder except on the evidence of two or three witnesses."],[5,20,"As for those who persist in sin, rebuke them in the presence of all, so that the rest may stand in fear."],[5,21,"In the presence of God and of Christ Jesus and of the elect angels I charge you to keep these rules without prejudging, doing nothing from partiality."],[5,22,"Do not be hasty in the laying on of hands, nor take part in the sins of others; keep yourself pure."]]},"2 Corinthians 13:14":{"b":"2 Corinthians","v":[[13,14,"The grace of the Lord Jesus Christ and the love of God and the fellowship of the Holy Spirit be with you all."]]},"2 Peter 1:20-21":{"b":"2 Peter","v":[[1,20,"knowing this first of all, that no prophecy of Scripture comes from someone's own interpretation."],[1,21,"For no prophecy was ever produced by the will of man, but men spoke from God as they were carried along by the Holy Spirit."]]},"2 Timothy 3:16-17":{"b":"2 Timothy","v":[[3,16,"All Scripture is breathed out by God and profitable for teaching, for reproof, for correction, and for training in righteousness,"],[3,17,"that the man of God may be complete, equipped for every good work."]]},"Acts 17:30-31":{"b":"Acts","v":[[17,30,"The times of ignorance God overlooked, but now he commands all people everywhere to repent,"],[17,31,"because he has fixed a day on which he will judge the world in righteousness by a man whom he has appointed; and of this he has given assurance to all by raising him from the dead.”"]]},"Acts 17:31":{"b":"Acts","v":[[17,31,"because he has fixed a day on which he will judge the world in righteousness by a man whom he has appointed; and of this he has given assurance to all by raising him from the dead.”"]]},"Acts 1:9-11":{"b":"Acts","v":[[1,9,"And when he had said these things, as they were looking on, he was lifted up, and a cloud took him out of their sight."],[1,10,"And while they were gazing into heaven as he went, behold, two men stood by them in white robes,"],[1,11,"and said, “Men of Galilee, why do you stand looking into heaven? This Jesus, who was taken up from you into heaven, will come in the same way as you saw him go into heaven.”"]]},"Acts 2:38":{"b":"Acts","v":[[2,38,"And Peter said to them, “Repent and be baptized every one of you in the name of Jesus Christ for the forgiveness of your sins, and you will receive the gift of the Holy Spirit."]]},"Acts 5:3-4":{"b":"Acts","v":[[5,3,"But Peter said, “Ananias, why has Satan filled your heart to lie to the Holy Spirit and to keep back for yourself part of the proceeds of the land?"],[5,4,"While it remained unsold, did it not remain your own? And after it was sold, was it not at your disposal? Why is it that you have contrived this deed in your heart? You have not lied to man but to God.”"]]},"Colossians 1:16-17":{"b":"Colossians","v":[[1,16,"For by him all things were created, in heaven and on earth, visible and invisible, whether thrones or dominions or rulers or authorities — all things were created through him and for him."],[1,17,"And he is before all things, and in him all things hold together."]]},"Colossians 2:8":{"b":"Colossians","v":[[2,8,"See to it that no one takes you captive by philosophy and empty deceit, according to human tradition, according to the elemental spirits of the world, and not according to Christ."]]},"Colossians 2:9":{"b":"Colossians","v":[[2,9,"For in him the whole fullness of deity dwells bodily,"]]},"Colossians 3:1-11":{"b":"Colossians","v":[[3,1,"If then you have been raised with Christ, seek the things that are above, where Christ is, seated at the right hand of God."],[3,2,"Set your minds on things that are above, not on things that are on earth."],[3,3,"For you have died, and your life is hidden with Christ in God."],[3,4,"When Christ who is your life appears, then you also will appear with him in glory."],[3,5,"Put to death therefore what is earthly in you: sexual immorality, impurity, passion, evil desire, and covetousness, which is idolatry."],[3,6,"On account of these the wrath of God is coming."],[3,7,"In these you too once walked, when you were living in them."],[3,8,"But now you must put them all away: anger, wrath, malice, slander, and obscene talk from your mouth."],[3,9,"Do not lie to one another, seeing that you have put off the old self with its practices"],[3,10,"and have put on the new self, which is being renewed in knowledge after the image of its creator."],[3,11,"Here there is not Greek and Jew, circumcised and uncircumcised, barbarian, Scythian, slave, free; but Christ is all, and in all."]]},"Deuteronomy 32:4":{"b":"Deuteronomy","v":[[32,4,"“The Rock, his work is perfect, for all his ways are justice. A God of faithfulness and without iniquity, just and upright is he."]]},"Ephesians 1:22-23":{"b":"Ephesians","v":[[1,22,"And he put all things under his feet and gave him as head over all things to the church,"],[1,23,"which is his body, the fullness of him who fills all in all."]]},"Ephesians 1:3-11":{"b":"Ephesians","v":[[1,3,"Blessed be the God and Father of our Lord Jesus Christ, who has blessed us in Christ with every spiritual blessing in the heavenly places,"],[1,4,"even as he chose us in him before the foundation of the world, that we should be holy and blameless before him. In love"],[1,5,"he predestined us for adoption to himself as sons through Jesus Christ, according to the purpose of his will,"],[1,6,"to the praise of his glorious grace, with which he has blessed us in the Beloved."],[1,7,"In him we have redemption through his blood, the forgiveness of our trespasses, according to the riches of his grace,"],[1,8,"which he lavished upon us, in all wisdom and insight"],[1,9,"making known to us the mystery of his will, according to his purpose, which he set forth in Christ"],[1,10,"as a plan for the fullness of time, to unite all things in him, things in heaven and things on earth."],[1,11,"In him we have obtained an inheritance, having been predestined according to the purpose of him who works all things according to the counsel of his will,"]]},"Ephesians 2:1-3":{"b":"Ephesians","v":[[2,1,"And you were dead in the trespasses and sins"],[2,2,"in which you once walked, following the course of this world, following the prince of the power of the air, the spirit that is now at work in the sons of disobedience —"],[2,3,"among whom we all once lived in the passions of our flesh, carrying out the desires of the body and the mind, and were by nature children of wrath, like the rest of mankind."]]},"Ephesians 2:8-10":{"b":"Ephesians","v":[[2,8,"For by grace you have been saved through faith. And this is not your own doing; it is the gift of God,"],[2,9,"not a result of works, so that no one may boast."],[2,10,"For we are his workmanship, created in Christ Jesus for good works, which God prepared beforehand, that we should walk in them."]]},"Ephesians 5:23":{"b":"Ephesians","v":[[5,23,"For the husband is the head of the wife even as Christ is the head of the church, his body, and is himself its Savior."]]},"Galatians 2:20":{"b":"Galatians","v":[[2,20,"I have been crucified with Christ. It is no longer I who live, but Christ who lives in me. And the life I now live in the flesh I live by faith in the Son of God, who loved me and gave himself for me."]]},"Galatians 5:22-25":{"b":"Galatians","v":[[5,22,"But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faithfulness,"],[5,23,"gentleness, self-control; against such things there is no law."],[5,24,"And those who belong to Christ Jesus have crucified the flesh with its passions and desires."],[5,25,"If we live by the Spirit, let us also keep in step with the Spirit."]]},"Genesis 1:1":{"b":"Genesis","v":[[1,1,"In the beginning, God created the heavens and the earth."]]},"Genesis 1:1-31":{"b":"Genesis","v":[[1,1,"In the beginning, God created the heavens and the earth."],[1,2,"The earth was without form and void, and darkness was over the face of the deep. And the Spirit of God was hovering over the face of the waters."],[1,3,"And God said, “Let there be light,” and there was light."],[1,4,"And God saw that the light was good. And God separated the light from the darkness."],[1,5,"God called the light Day, and the darkness he called Night. And there was evening and there was morning, the first day."],[1,6,"And God said, “Let there be an expanse in the midst of the waters, and let it separate the waters from the waters.”"],[1,7,"And God made the expanse and separated the waters that were under the expanse from the waters that were above the expanse. And it was so."],[1,8,"And God called the expanse Heaven. And there was evening and there was morning, the second day."],[1,9,"And God said, “Let the waters under the heavens be gathered together into one place, and let the dry land appear.” And it was so."],[1,10,"God called the dry land Earth, and the waters that were gathered together he called Seas. And God saw that it was good."],[1,11,"And God said, “Let the earth sprout vegetation, plants yielding seed, and fruit trees bearing fruit in which is their seed, each according to its kind, on the earth.” And it was so."],[1,12,"The earth brought forth vegetation, plants yielding seed according to their own kinds, and trees bearing fruit in which is their seed, each according to its kind. And God saw that it was good."],[1,13,"And there was evening and there was morning, the third day."],[1,14,"And God said, “Let there be lights in the expanse of the heavens to separate the day from the night. And let them be for signs and for seasons, and for days and years,"],[1,15,"and let them be lights in the expanse of the heavens to give light upon the earth.” And it was so."],[1,16,"And God made the two great lights — the greater light to rule the day and the lesser light to rule the night — and the stars."],[1,17,"And God set them in the expanse of the heavens to give light on the earth,"],[1,18,"to rule over the day and over the night, and to separate the light from the darkness. And God saw that it was good."],[1,19,"And there was evening and there was morning, the fourth day."],[1,20,"And God said, “Let the waters swarm with swarms of living creatures, and let birds fly above the earth across the expanse of the heavens.”"],[1,21,"So God created the great sea creatures and every living creature that moves, with which the waters swarm, according to their kinds, and every winged bird according to its kind. And God saw that it was good."],[1,22,"And God blessed them, saying, “Be fruitful and multiply and fill the waters in the seas, and let birds multiply on the earth.”"],[1,23,"And there was evening and there was morning, the fifth day."],[1,24,"And God said, “Let the earth bring forth living creatures according to their kinds — livestock and creeping things and beasts of the earth according to their kinds.” And it was so."],[1,25,"And God made the beasts of the earth according to their kinds and the livestock according to their kinds, and everything that creeps on the ground according to its kind. And God saw that it was good."],[1,26,"Then God said, “Let us make man in our image, after our likeness. And let them have dominion over the fish of the sea and over the birds of the heavens and over the livestock and over all the earth and over every creeping thing that creeps on the earth.”"],[1,27,"So God created man in his own image, in the image of God he created him; male and female he created them."],[1,28,"And God blessed them. And God said to them, “Be fruitful and multiply and fill the earth and subdue it, and have dominion over the fish of the sea and over the birds of the heavens and over every living thing that moves on the earth.”"],[1,29,"And God said, “Behold, I have given you every plant yielding seed that is on the face of all the earth, and every tree with seed in its fruit. You shall have them for food."],[1,30,"And to every beast of the earth and to every bird of the heavens and to everything that creeps on the earth, everything that has the breath of life, I have given every green plant for food.” And it was so."],[1,31,"And God saw everything that he had made, and behold, it was very good. And there was evening and there was morning, the sixth day."]]},"Genesis 2:24":{"b":"Genesis","v":[[2,24,"Therefore a man shall leave his father and his mother and hold fast to his wife, and they shall become one flesh."]]},"Genesis 2:7":{"b":"Genesis","v":[[2,7,"then the LORD God formed the man of dust from the ground and breathed into his nostrils the breath of life, and the man became a living creature."]]},"Genesis 3:1-24":{"b":"Genesis","v":[[3,1,"Now the serpent was more crafty than any other beast of the field that the LORD God had made. He said to the woman, “Did God actually say, ‘You shall not eat of any tree in the garden’?”"],[3,2,"And the woman said to the serpent, “We may eat of the fruit of the trees in the garden,"],[3,3,"but God said, ‘You shall not eat of the fruit of the tree that is in the midst of the garden, neither shall you touch it, lest you die.’”"],[3,4,"But the serpent said to the woman, “You will not surely die."],[3,5,"For God knows that when you eat of it your eyes will be opened, and you will be like God, knowing good and evil.”"],[3,6,"So when the woman saw that the tree was good for food, and that it was a delight to the eyes, and that the tree was to be desired to make one wise, she took of its fruit and ate, and she also gave some to her husband who was with her, and he ate."],[3,7,"Then the eyes of both were opened, and they knew that they were naked. And they sewed fig leaves together and made themselves loincloths."],[3,8,"And they heard the sound of the LORD God walking in the garden in the cool of the day, and the man and his wife hid themselves from the presence of the LORD God among the trees of the garden."],[3,9,"But the LORD God called to the man and said to him, “Where are you?”"],[3,10,"And he said, “I heard the sound of you in the garden, and I was afraid, because I was naked, and I hid myself.”"],[3,11,"He said, “Who told you that you were naked? Have you eaten of the tree of which I commanded you not to eat?”"],[3,12,"The man said, “The woman whom you gave to be with me, she gave me fruit of the tree, and I ate.”"],[3,13,"Then the LORD God said to the woman, “What is this that you have done?” The woman said, “The serpent deceived me, and I ate.”"],[3,14,"The LORD God said to the serpent, “Because you have done this, cursed are you above all livestock and above all beasts of the field; on your belly you shall go, and dust you shall eat all the days of your life."],[3,15,"I will put enmity between you and the woman, and between your offspring and her offspring; he shall bruise your head, and you shall bruise his heel.”"],[3,16,"To the woman he said, “I will surely multiply your pain in childbearing; in pain you shall bring forth children. Your desire shall be contrary to your husband, but he shall rule over you.”"],[3,17,"And to Adam he said, “Because you have listened to the voice of your wife and have eaten of the tree of which I commanded you, ‘You shall not eat of it,’ cursed is the ground because of you; in pain you shall eat of it all the days of your life;"],[3,18,"thorns and thistles it shall bring forth for you; and you shall eat the plants of the field."],[3,19,"By the sweat of your face you shall eat bread, till you return to the ground, for out of it you were taken; for you are dust, and to dust you shall return.”"],[3,20,"The man called his wife's name Eve, because she was the mother of all living."],[3,21,"And the LORD God made for Adam and for his wife garments of skins and clothed them."],[3,22,"Then the LORD God said, “Behold, the man has become like one of us in knowing good and evil. Now, lest he reach out his hand and take also of the tree of life and eat, and live forever — ”"],[3,23,"therefore the LORD God sent him out from the garden of Eden to work the ground from which he was taken."],[3,24,"He drove out the man, and at the east of the garden of Eden he placed the cherubim and a flaming sword that turned every way to guard the way to the tree of life."]]},"Hebrews 13:4":{"b":"Hebrews","v":[[13,4,"Let marriage be held in honor among all, and let the marriage bed be undefiled, for God will judge the sexually immoral and adulterous."]]},"Hebrews 1:1-13":{"b":"Hebrews","v":[[1,1,"Long ago, at many times and in many ways, God spoke to our fathers by the prophets,"],[1,2,"but in these last days he has spoken to us by his Son, whom he appointed the heir of all things, through whom also he created the world."],[1,3,"He is the radiance of the glory of God and the exact imprint of his nature, and he upholds the universe by the word of his power. After making purification for sins, he sat down at the right hand of the Majesty on high,"],[1,4,"having become as much superior to angels as the name he has inherited is more excellent than theirs."],[1,5,"For to which of the angels did God ever say, “You are my Son, today I have begotten you”? Or again, “I will be to him a father, and he shall be to me a son”?"],[1,6,"And again, when he brings the firstborn into the world, he says, “Let all God's angels worship him.”"],[1,7,"Of the angels he says, “He makes his angels winds, and his ministers a flame of fire.”"],[1,8,"But of the Son he says, “Your throne, O God, is forever and ever, the scepter of uprightness is the scepter of your kingdom."],[1,9,"You have loved righteousness and hated wickedness; therefore God, your God, has anointed you with the oil of gladness beyond your companions.”"],[1,10,"And, “You, Lord, laid the foundation of the earth in the beginning, and the heavens are the work of your hands;"],[1,11,"they will perish, but you remain; they will all wear out like a garment,"],[1,12,"like a robe you will roll them up, like a garment they will be changed. But you are the same, and your years will have no end.”"],[1,13,"And to which of the angels has he ever said, “Sit at my right hand until I make your enemies a footstool for your feet”?"]]},"Hebrews 2:14-18":{"b":"Hebrews","v":[[2,14,"Since therefore the children share in flesh and blood, he himself likewise partook of the same things, that through death he might destroy the one who has the power of death, that is, the devil,"],[2,15,"and deliver all those who through fear of death were subject to lifelong slavery."],[2,16,"For surely it is not angels that he helps, but he helps the offspring of Abraham."],[2,17,"Therefore he had to be made like his brothers in every respect, so that he might become a merciful and faithful high priest in the service of God, to make propitiation for the sins of the people."],[2,18,"For because he himself has suffered when tempted, he is able to help those who are being tempted."]]},"Hebrews 4:15":{"b":"Hebrews","v":[[4,15,"For we do not have a high priest who is unable to sympathize with our weaknesses, but one who in every respect has been tempted as we are, yet without sin."]]},"Isaiah 45:5-7":{"b":"Isaiah","v":[[45,5,"I am the LORD, and there is no other, besides me there is no God; I equip you, though you do not know me,"],[45,6,"that people may know, from the rising of the sun and from the west, that there is none besides me; I am the LORD, and there is no other."],[45,7,"I form light and create darkness; I make well-being and create calamity; I am the LORD, who does all these things."]]},"Isaiah 53:1-12":{"b":"Isaiah","v":[[53,1,"Who has believed what he has heard from us? And to whom has the arm of the LORD been revealed?"],[53,2,"For he grew up before him like a young plant, and like a root out of dry ground; he had no form or majesty that we should look at him, and no beauty that we should desire him."],[53,3,"He was despised and rejected by men, a man of sorrows and acquainted with grief; and as one from whom men hide their faces he was despised, and we esteemed him not."],[53,4,"Surely he has borne our griefs and carried our sorrows; yet we esteemed him stricken, smitten by God, and afflicted."],[53,5,"But he was pierced for our transgressions; he was crushed for our iniquities; upon him was the chastisement that brought us peace, and with his wounds we are healed."],[53,6,"All we like sheep have gone astray; we have turned — every one — to his own way; and the LORD has laid on him the iniquity of us all."],[53,7,"He was oppressed, and he was afflicted, yet he opened not his mouth; like a lamb that is led to the slaughter, and like a sheep that before its shearers is silent, so he opened not his mouth."],[53,8,"By oppression and judgment he was taken away; and as for his generation, who considered that he was cut off out of the land of the living, stricken for the transgression of my people?"],[53,9,"And they made his grave with the wicked and with a rich man in his death, although he had done no violence, and there was no deceit in his mouth."],[53,10,"Yet it was the will of the LORD to crush him; he has put him to grief; when his soul makes an offering for guilt, he shall see his offspring; he shall prolong his days; the will of the LORD shall prosper in his hand."],[53,11,"Out of the anguish of his soul he shall see and be satisfied; by his knowledge shall the righteous one, my servant, make many to be accounted righteous, and he shall bear their iniquities."],[53,12,"Therefore I will divide him a portion with the many, and he shall divide the spoil with the strong, because he poured out his soul to death and was numbered with the transgressors; yet he bore the sin of many, and makes intercession for the transgressors."]]},"James 1:17-18":{"b":"James","v":[[1,17,"Every good gift and every perfect gift is from above, coming down from the Father of lights, with whom there is no variation or shadow due to change."],[1,18,"Of his own will he brought us forth by the word of truth, that we should be a kind of firstfruits of his creatures."]]},"Jeremiah 1:5":{"b":"Jeremiah","v":[[1,5,"“Before I formed you in the womb I knew you, and before you were born I consecrated you; I appointed you a prophet to the nations.”"]]},"John 14:16-17":{"b":"John","v":[[14,16,"And I will ask the Father, and he will give you another Helper, to be with you forever,"],[14,17,"even the Spirit of truth, whom the world cannot receive, because it neither sees him nor knows him. You know him, for he dwells with you and will be in you."]]},"John 14:6":{"b":"John","v":[[14,6,"Jesus said to him, “I am the way, and the truth, and the life. No one comes to the Father except through me."]]},"John 16:7-15":{"b":"John","v":[[16,7,"Nevertheless, I tell you the truth: it is to your advantage that I go away, for if I do not go away, the Helper will not come to you. But if I go, I will send him to you."],[16,8,"And when he comes, he will convict the world concerning sin and righteousness and judgment:"],[16,9,"concerning sin, because they do not believe in me;"],[16,10,"concerning righteousness, because I go to the Father, and you will see me no longer;"],[16,11,"concerning judgment, because the ruler of this world is judged."],[16,12,"“I still have many things to say to you, but you cannot bear them now."],[16,13,"When the Spirit of truth comes, he will guide you into all the truth, for he will not speak on his own authority, but whatever he hears he will speak, and he will declare to you the things that are to come."],[16,14,"He will glorify me, for he will take what is mine and declare it to you."],[16,15,"All that the Father has is mine; therefore I said that he will take what is mine and declare it to you."]]},"John 1:1-14":{"b":"John","v":[[1,1,"In the beginning was the Word, and the Word was with God, and the Word was God."],[1,2,"He was in the beginning with God."],[1,3,"All things were made through him, and without him was not any thing made that was made."],[1,4,"In him was life, and the life was the light of men."],[1,5,"The light shines in the darkness, and the darkness has not overcome it."],[1,6,"There was a man sent from God, whose name was John."],[1,7,"He came as a witness, to bear witness about the light, that all might believe through him."],[1,8,"He was not the light, but came to bear witness about the light."],[1,9,"The true light, which gives light to everyone, was coming into the world."],[1,10,"He was in the world, and the world was made through him, yet the world did not know him."],[1,11,"He came to his own, and his own people did not receive him."],[1,12,"But to all who did receive him, who believed in his name, he gave the right to become children of God,"],[1,13,"who were born, not of blood nor of the will of the flesh nor of the will of man, but of God."],[1,14,"And the Word became flesh and dwelt among us, and we have seen his glory, glory as of the only Son from the Father, full of grace and truth."]]},"John 3:13":{"b":"John","v":[[3,13,"No one has ascended into heaven except he who descended from heaven, the Son of Man."]]},"John 6:44-46":{"b":"John","v":[[6,44,"No one can come to me unless the Father who sent me draws him. And I will raise him up on the last day."],[6,45,"It is written in the Prophets, ‘And they will all be taught by God.’ Everyone who has heard and learned from the Father comes to me —"],[6,46,"not that anyone has seen the Father except he who is from God; he has seen the Father."]]},"John 8:10-11":{"b":"John","v":[[8,10,"Jesus stood up and said to her, “Woman, where are they? Has no one condemned you?”"],[8,11,"She said, “No one, Lord.” And Jesus said, “Neither do I condemn you; go, and from now on sin no more.”]]"]]},"Joshua 24:15":{"b":"Joshua","v":[[24,15,"And if it is evil in your eyes to serve the LORD, choose this day whom you will serve, whether the gods your fathers served in the region beyond the River, or the gods of the Amorites in whose land you dwell. But as for me and my house, we will serve the LORD.”"]]},"Luke 12:47-48":{"b":"Luke","v":[[12,47,"And that servant who knew his master's will but did not get ready or act according to his will, will receive a severe beating."],[12,48,"But the one who did not know, and did what deserved a beating, will receive a light beating. Everyone to whom much was given, of him much will be required, and from him to whom they entrusted much, they will demand the more."]]},"Luke 1:41":{"b":"Luke","v":[[1,41,"And when Elizabeth heard the greeting of Mary, the baby leaped in her womb. And Elizabeth was filled with the Holy Spirit,"]]},"Luke 22:19-20":{"b":"Luke","v":[[22,19,"And he took bread, and when he had given thanks, he broke it and gave it to them, saying, “This is my body, which is given for you. Do this in remembrance of me.”"],[22,20,"And likewise the cup after they had eaten, saying, “This cup that is poured out for you is the new covenant in my blood."]]},"Luke 23:39-43":{"b":"Luke","v":[[23,39,"One of the criminals who were hanged railed at him, saying, “Are you not the Christ? Save yourself and us!”"],[23,40,"But the other rebuked him, saying, “Do you not fear God, since you are under the same sentence of condemnation?"],[23,41,"And we indeed justly, for we are receiving the due reward of our deeds; but this man has done nothing wrong.”"],[23,42,"And he said, “Jesus, remember me when you come into your kingdom.”"],[23,43,"And he said to him, “Truly, I say to you, today you will be with me in paradise.”"]]},"Malachi 3:6":{"b":"Malachi","v":[[3,6,"“For I the LORD do not change; therefore you, O children of Jacob, are not consumed."]]},"Mark 1:15":{"b":"Mark","v":[[1,15,"and saying, “The time is fulfilled, and the kingdom of God is at hand; repent and believe in the gospel.”"]]},"Mark 3:29":{"b":"Mark","v":[[3,29,"but whoever blasphemes against the Holy Spirit never has forgiveness, but is guilty of an eternal sin” —"]]},"Mark 7:1-13":{"b":"Mark","v":[[7,1,"Now when the Pharisees gathered to him, with some of the scribes who had come from Jerusalem,"],[7,2,"they saw that some of his disciples ate with hands that were defiled, that is, unwashed."],[7,3,"(For the Pharisees and all the Jews do not eat unless they wash their hands properly, holding to the tradition of the elders,"],[7,4,"and when they come from the marketplace, they do not eat unless they wash. And there are many other traditions that they observe, such as the washing of cups and pots and copper vessels and dining couches. )"],[7,5,"And the Pharisees and the scribes asked him, “Why do your disciples not walk according to the tradition of the elders, but eat with defiled hands?”"],[7,6,"And he said to them, “Well did Isaiah prophesy of you hypocrites, as it is written, “‘This people honors me with their lips, but their heart is far from me;"],[7,7,"in vain do they worship me, teaching as doctrines the commandments of men.’"],[7,8,"You leave the commandment of God and hold to the tradition of men.”"],[7,9,"And he said to them, “You have a fine way of rejecting the commandment of God in order to establish your tradition!"],[7,10,"For Moses said, ‘Honor your father and your mother’; and, ‘Whoever reviles father or mother must surely die.’"],[7,11,"But you say, ‘If a man tells his father or his mother, “Whatever you would have gained from me is Corban”’ (that is, given to God) —"],[7,12,"then you no longer permit him to do anything for his father or mother,"],[7,13,"thus making void the word of God by your tradition that you have handed down. And many such things you do.”"]]},"Matthew 19:4-9":{"b":"Matthew","v":[[19,4,"He answered, “Have you not read that he who created them from the beginning made them male and female,"],[19,5,"and said, ‘Therefore a man shall leave his father and his mother and hold fast to his wife, and the two shall become one flesh’?"],[19,6,"So they are no longer two but one flesh. What therefore God has joined together, let not man separate.”"],[19,7,"They said to him, “Why then did Moses command one to give a certificate of divorce and to send her away?”"],[19,8,"He said to them, “Because of your hardness of heart Moses allowed you to divorce your wives, but from the beginning it was not so."],[19,9,"And I say to you: whoever divorces his wife, except for sexual immorality, and marries another, commits adultery.”"]]},"Matthew 25:31-46":{"b":"Matthew","v":[[25,31,"“When the Son of Man comes in his glory, and all the angels with him, then he will sit on his glorious throne."],[25,32,"Before him will be gathered all the nations, and he will separate people one from another as a shepherd separates the sheep from the goats."],[25,33,"And he will place the sheep on his right, but the goats on the left."],[25,34,"Then the King will say to those on his right, ‘Come, you who are blessed by my Father, inherit the kingdom prepared for you from the foundation of the world."],[25,35,"For I was hungry and you gave me food, I was thirsty and you gave me drink, I was a stranger and you welcomed me,"],[25,36,"I was naked and you clothed me, I was sick and you visited me, I was in prison and you came to me.’"],[25,37,"Then the righteous will answer him, saying, ‘Lord, when did we see you hungry and feed you, or thirsty and give you drink?"],[25,38,"And when did we see you a stranger and welcome you, or naked and clothe you?"],[25,39,"And when did we see you sick or in prison and visit you?’"],[25,40,"And the King will answer them, ‘Truly, I say to you, as you did it to one of the least of these my brothers, you did it to me.’"],[25,41,"“Then he will say to those on his left, ‘Depart from me, you cursed, into the eternal fire prepared for the devil and his angels."],[25,42,"For I was hungry and you gave me no food, I was thirsty and you gave me no drink,"],[25,43,"I was a stranger and you did not welcome me, naked and you did not clothe me, sick and in prison and you did not visit me.’"],[25,44,"Then they also will answer, saying, ‘Lord, when did we see you hungry or thirsty or a stranger or naked or sick or in prison, and did not minister to you?’"],[25,45,"Then he will answer them, saying, ‘Truly, I say to you, as you did not do it to one of the least of these, you did not do it to me.’"],[25,46,"And these will go away into eternal punishment, but the righteous into eternal life.”"]]},"Matthew 28:18-20":{"b":"Matthew","v":[[28,18,"And Jesus came and said to them, “All authority in heaven and on earth has been given to me."],[28,19,"Go therefore and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,"],[28,20,"teaching them to observe all that I have commanded you. And behold, I am with you always, to the end of the age.”"]]},"Matthew 28:19":{"b":"Matthew","v":[[28,19,"Go therefore and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,"]]},"Nehemiah 9:6":{"b":"Nehemiah","v":[[9,6,"“You are the LORD, you alone. You have made heaven, the heaven of heavens, with all their host, the earth and all that is on it, the seas and all that is in them; and you preserve all of them; and the host of heaven worships you."]]},"Philippians 2:5-11":{"b":"Philippians","v":[[2,5,"Have this mind among yourselves, which is yours in Christ Jesus,"],[2,6,"who, though he was in the form of God, did not count equality with God a thing to be grasped,"],[2,7,"but emptied himself, by taking the form of a servant, being born in the likeness of men."],[2,8,"And being found in human form, he humbled himself by becoming obedient to the point of death, even death on a cross."],[2,9,"Therefore God has highly exalted him and bestowed on him the name that is above every name,"],[2,10,"so that at the name of Jesus every knee should bow, in heaven and on earth and under the earth,"],[2,11,"and every tongue confess that Jesus Christ is Lord, to the glory of God the Father."]]},"Psalm 139:1-24":{"b":"Psalm","v":[[139,1,"O LORD, you have searched me and known me!"],[139,2,"You know when I sit down and when I rise up; you discern my thoughts from afar."],[139,3,"You search out my path and my lying down and are acquainted with all my ways."],[139,4,"Even before a word is on my tongue, behold, O LORD, you know it altogether."],[139,5,"You hem me in, behind and before, and lay your hand upon me."],[139,6,"Such knowledge is too wonderful for me; it is high; I cannot attain it."],[139,7,"Where shall I go from your Spirit? Or where shall I flee from your presence?"],[139,8,"If I ascend to heaven, you are there! If I make my bed in Sheol, you are there!"],[139,9,"If I take the wings of the morning and dwell in the uttermost parts of the sea,"],[139,10,"even there your hand shall lead me, and your right hand shall hold me."],[139,11,"If I say, “Surely the darkness shall cover me, and the light about me be night,”"],[139,12,"even the darkness is not dark to you; the night is bright as the day, for darkness is as light with you."],[139,13,"For you formed my inward parts; you knitted me together in my mother's womb."],[139,14,"I praise you, for I am fearfully and wonderfully made. Wonderful are your works; my soul knows it very well."],[139,15,"My frame was not hidden from you, when I was being made in secret, intricately woven in the depths of the earth."],[139,16,"Your eyes saw my unformed substance; in your book were written, every one of them, the days that were formed for me, when as yet there was none of them."],[139,17,"How precious to me are your thoughts, O God! How vast is the sum of them!"],[139,18,"If I would count them, they are more than the sand. I awake, and I am still with you."],[139,19,"Oh that you would slay the wicked, O God! O men of blood, depart from me!"],[139,20,"They speak against you with malicious intent; your enemies take your name in vain."],[139,21,"Do I not hate those who hate you, O LORD? And do I not loathe those who rise up against you?"],[139,22,"I hate them with complete hatred; I count them my enemies."],[139,23,"Search me, O God, and know my heart! Try me and know my thoughts!"],[139,24,"And see if there be any grievous way in me, and lead me in the way everlasting!"]]},"Psalm 139:13-16":{"b":"Psalm","v":[[139,13,"For you formed my inward parts; you knitted me together in my mother's womb."],[139,14,"I praise you, for I am fearfully and wonderfully made. Wonderful are your works; my soul knows it very well."],[139,15,"My frame was not hidden from you, when I was being made in secret, intricately woven in the depths of the earth."],[139,16,"Your eyes saw my unformed substance; in your book were written, every one of them, the days that were formed for me, when as yet there was none of them."]]},"Psalm 19:1-4":{"b":"Psalm","v":[[19,1,"The heavens declare the glory of God, and the sky above proclaims his handiwork."],[19,2,"Day to day pours out speech, and night to night reveals knowledge."],[19,3,"There is no speech, nor are there words, whose voice is not heard."],[19,4,"Their voice goes out through all the earth, and their words to the end of the world. In them he has set a tent for the sun,"]]},"Psalm 19:7-11":{"b":"Psalm","v":[[19,7,"The law of the LORD is perfect, reviving the soul; the testimony of the LORD is sure, making wise the simple;"],[19,8,"the precepts of the LORD are right, rejoicing the heart; the commandment of the LORD is pure, enlightening the eyes;"],[19,9,"the fear of the LORD is clean, enduring forever; the rules of the LORD are true, and righteous altogether."],[19,10,"More to be desired are they than gold, even much fine gold; sweeter also than honey and drippings of the honeycomb."],[19,11,"Moreover, by them is your servant warned; in keeping them there is great reward."]]},"Psalm 8:4-5":{"b":"Psalm","v":[[8,4,"what is man that you are mindful of him, and the son of man that you care for him?"],[8,5,"Yet you have made him a little lower than the heavenly beings and crowned him with glory and honor."]]},"Psalm 90:2":{"b":"Psalm","v":[[90,2,"Before the mountains were brought forth, or ever you had formed the earth and the world, from everlasting to everlasting you are God."]]},"Psalm 99:9":{"b":"Psalm","v":[[99,9,"Exalt the LORD our God, and worship at his holy mountain; for the LORD our God is holy!"]]},"Revelation 1:5-6":{"b":"Revelation","v":[[1,5,"and from Jesus Christ the faithful witness, the firstborn of the dead, and the ruler of kings on earth. To him who loves us and has freed us from our sins by his blood"],[1,6,"and made us a kingdom, priests to his God and Father, to him be glory and dominion forever and ever. Amen."]]},"Revelation 20:10-21:27":{"b":"Revelation","v":[[20,10,"and the devil who had deceived them was thrown into the lake of fire and sulfur where the beast and the false prophet were, and they will be tormented day and night forever and ever."],[20,11,"Then I saw a great white throne and him who was seated on it. From his presence earth and sky fled away, and no place was found for them."],[20,12,"And I saw the dead, great and small, standing before the throne, and books were opened. Then another book was opened, which is the book of life. And the dead were judged by what was written in the books, according to what they had done."],[20,13,"And the sea gave up the dead who were in it, Death and Hades gave up the dead who were in them, and they were judged, each one of them, according to what they had done."],[20,14,"Then Death and Hades were thrown into the lake of fire. This is the second death, the lake of fire."],[20,15,"And if anyone's name was not found written in the book of life, he was thrown into the lake of fire."],[21,1,"Then I saw a new heaven and a new earth, for the first heaven and the first earth had passed away, and the sea was no more."],[21,2,"And I saw the holy city, new Jerusalem, coming down out of heaven from God, prepared as a bride adorned for her husband."],[21,3,"And I heard a loud voice from the throne saying, “Behold, the dwelling place of God is with man. He will dwell with them, and they will be his people, and God himself will be with them as their God."],[21,4,"He will wipe away every tear from their eyes, and death shall be no more, neither shall there be mourning, nor crying, nor pain anymore, for the former things have passed away.”"],[21,5,"And he who was seated on the throne said, “Behold, I am making all things new.” Also he said, “Write this down, for these words are trustworthy and true.”"],[21,6,"And he said to me, “It is done! I am the Alpha and the Omega, the beginning and the end. To the thirsty I will give from the spring of the water of life without payment."],[21,7,"The one who conquers will have this heritage, and I will be his God and he will be my son."],[21,8,"But as for the cowardly, the faithless, the detestable, as for murderers, the sexually immoral, sorcerers, idolaters, and all liars, their portion will be in the lake that burns with fire and sulfur, which is the second death.”"],[21,9,"Then came one of the seven angels who had the seven bowls full of the seven last plagues and spoke to me, saying, “Come, I will show you the Bride, the wife of the Lamb.”"],[21,10,"And he carried me away in the Spirit to a great, high mountain, and showed me the holy city Jerusalem coming down out of heaven from God,"],[21,11,"having the glory of God, its radiance like a most rare jewel, like a jasper, clear as crystal."],[21,12,"It had a great, high wall, with twelve gates, and at the gates twelve angels, and on the gates the names of the twelve tribes of the sons of Israel were inscribed —"],[21,13,"on the east three gates, on the north three gates, on the south three gates, and on the west three gates."],[21,14,"And the wall of the city had twelve foundations, and on them were the twelve names of the twelve apostles of the Lamb."],[21,15,"And the one who spoke with me had a measuring rod of gold to measure the city and its gates and walls."],[21,16,"The city lies foursquare, its length the same as its width. And he measured the city with his rod, 12,000 stadia. Its length and width and height are equal."],[21,17,"He also measured its wall, 144 cubits by human measurement, which is also an angel's measurement."],[21,18,"The wall was built of jasper, while the city was pure gold, like clear glass."],[21,19,"The foundations of the wall of the city were adorned with every kind of jewel. The first was jasper, the second sapphire, the third agate, the fourth emerald,"],[21,20,"the fifth onyx, the sixth carnelian, the seventh chrysolite, the eighth beryl, the ninth topaz, the tenth chrysoprase, the eleventh jacinth, the twelfth amethyst."],[21,21,"And the twelve gates were twelve pearls, each of the gates made of a single pearl, and the street of the city was pure gold, like transparent glass."],[21,22,"And I saw no temple in the city, for its temple is the Lord God the Almighty and the Lamb."],[21,23,"And the city has no need of sun or moon to shine on it, for the glory of God gives it light, and its lamp is the Lamb."],[21,24,"By its light will the nations walk, and the kings of the earth will bring their glory into it,"],[21,25,"and its gates will never be shut by day — and there will be no night there."],[21,26,"They will bring into it the glory and the honor of the nations."],[21,27,"But nothing unclean will ever enter it, nor anyone who does what is detestable or false, but only those who are written in the Lamb's book of life."]]},"Romans 1:18-21":{"b":"Romans","v":[[1,18,"For the wrath of God is revealed from heaven against all ungodliness and unrighteousness of men, who by their unrighteousness suppress the truth."],[1,19,"For what can be known about God is plain to them, because God has shown it to them."],[1,20,"For his invisible attributes, namely, his eternal power and divine nature, have been clearly perceived, ever since the creation of the world, in the things that have been made. So they are without excuse."],[1,21,"For although they knew God, they did not honor him as God or give thanks to him, but they became futile in their thinking, and their foolish hearts were darkened."]]},"Romans 1:19-20":{"b":"Romans","v":[[1,19,"For what can be known about God is plain to them, because God has shown it to them."],[1,20,"For his invisible attributes, namely, his eternal power and divine nature, have been clearly perceived, ever since the creation of the world, in the things that have been made. So they are without excuse."]]},"Romans 2:12-16":{"b":"Romans","v":[[2,12,"For all who have sinned without the law will also perish without the law, and all who have sinned under the law will be judged by the law."],[2,13,"For it is not the hearers of the law who are righteous before God, but the doers of the law who will be justified."],[2,14,"For when Gentiles, who do not have the law, by nature do what the law requires, they are a law to themselves, even though they do not have the law."],[2,15,"They show that the work of the law is written on their hearts, while their conscience also bears witness, and their conflicting thoughts accuse or even excuse them"],[2,16,"on that day when, according to my gospel, God judges the secrets of men by Christ Jesus."]]},"Romans 3:19-31":{"b":"Romans","v":[[3,19,"Now we know that whatever the law says it speaks to those who are under the law, so that every mouth may be stopped, and the whole world may be held accountable to God."],[3,20,"For by works of the law no human being will be justified in his sight, since through the law comes knowledge of sin."],[3,21,"But now the righteousness of God has been manifested apart from the law, although the Law and the Prophets bear witness to it —"],[3,22,"the righteousness of God through faith in Jesus Christ for all who believe. For there is no distinction:"],[3,23,"for all have sinned and fall short of the glory of God,"],[3,24,"and are justified by his grace as a gift, through the redemption that is in Christ Jesus,"],[3,25,"whom God put forward as a propitiation by his blood, to be received by faith. This was to show God's righteousness, because in his divine forbearance he had passed over former sins."],[3,26,"It was to show his righteousness at the present time, so that he might be just and the justifier of the one who has faith in Jesus."],[3,27,"Then what becomes of our boasting? It is excluded. By what kind of law? By a law of works? No, but by the law of faith."],[3,28,"For we hold that one is justified by faith apart from works of the law."],[3,29,"Or is God the God of Jews only? Is he not the God of Gentiles also? Yes, of Gentiles also,"],[3,30,"since God is one — who will justify the circumcised by faith and the uncircumcised through faith."],[3,31,"Do we then overthrow the law by this faith? By no means! On the contrary, we uphold the law."]]},"Romans 3:23":{"b":"Romans","v":[[3,23,"for all have sinned and fall short of the glory of God,"]]},"Romans 5:12":{"b":"Romans","v":[[5,12,"Therefore, just as sin came into the world through one man, and death through sin, and so death spread to all men because all sinned —"]]},"Romans 5:8":{"b":"Romans","v":[[5,8,"but God shows his love for us in that while we were still sinners, Christ died for us."]]},"Romans 6:3-10":{"b":"Romans","v":[[6,3,"Do you not know that all of us who have been baptized into Christ Jesus were baptized into his death?"],[6,4,"We were buried therefore with him by baptism into death, in order that, just as Christ was raised from the dead by the glory of the Father, we too might walk in newness of life."],[6,5,"For if we have been united with him in a death like his, we shall certainly be united with him in a resurrection like his."],[6,6,"We know that our old self was crucified with him in order that the body of sin might be brought to nothing, so that we would no longer be enslaved to sin."],[6,7,"For one who has died has been set free from sin."],[6,8,"Now if we have died with Christ, we believe that we will also live with him."],[6,9,"We know that Christ, being raised from the dead, will never die again; death no longer has dominion over him."],[6,10,"For the death he died he died to sin, once for all, but the life he lives he lives to God."]]},"Romans 6:3-4":{"b":"Romans","v":[[6,3,"Do you not know that all of us who have been baptized into Christ Jesus were baptized into his death?"],[6,4,"We were buried therefore with him by baptism into death, in order that, just as Christ was raised from the dead by the glory of the Father, we too might walk in newness of life."]]},"Romans 8:11":{"b":"Romans","v":[[8,11,"If the Spirit of him who raised Jesus from the dead dwells in you, he who raised Christ Jesus from the dead will also give life to your mortal bodies through his Spirit who dwells in you."]]},"Song of Solomon 4:16-5:1":{"b":"Song of Solomon","v":[[4,16,"Awake, O north wind, and come, O south wind! Blow upon my garden, let its spices flow. Together in the Garden of Love She Let my beloved come to his garden, and eat its choicest fruits."],[5,1,"I came to my garden, my sister, my bride, I gathered my myrrh with my spice, I ate my honeycomb with my honey, I drank my wine with my milk. Others Eat, friends, drink, and be drunk with love!"]]},"Titus 1:5-2:1":{"b":"Titus","v":[[1,5,"This is why I left you in Crete, so that you might put what remained into order, and appoint elders in every town as I directed you —"],[1,6,"if anyone is above reproach, the husband of one wife, and his children are believers and not open to the charge of debauchery or insubordination."],[1,7,"For an overseer, as God's steward, must be above reproach. He must not be arrogant or quick-tempered or a drunkard or violent or greedy for gain,"],[1,8,"but hospitable, a lover of good, self-controlled, upright, holy, and disciplined."],[1,9,"He must hold firm to the trustworthy word as taught, so that he may be able to give instruction in sound doctrine and also to rebuke those who contradict it."],[1,10,"For there are many who are insubordinate, empty talkers and deceivers, especially those of the circumcision party."],[1,11,"They must be silenced, since they are upsetting whole families by teaching for shameful gain what they ought not to teach."],[1,12,"One of the Cretans, a prophet of their own, said, “Cretans are always liars, evil beasts, lazy gluttons.”"],[1,13,"This testimony is true. Therefore rebuke them sharply, that they may be sound in the faith,"],[1,14,"not devoting themselves to Jewish myths and the commands of people who turn away from the truth."],[1,15,"To the pure, all things are pure, but to the defiled and unbelieving, nothing is pure; but both their minds and their consciences are defiled."],[1,16,"They profess to know God, but they deny him by their works. They are detestable, disobedient, unfit for any good work."],[2,1,"But as for you, teach what accords with sound doctrine."]]},"Titus 3:4-7":{"b":"Titus","v":[[3,4,"But when the goodness and loving kindness of God our Savior appeared,"],[3,5,"he saved us, not because of works done by us in righteousness, but according to his own mercy, by the washing of regeneration and renewal of the Holy Spirit,"],[3,6,"whom he poured out on us richly through Jesus Christ our Savior,"],[3,7,"so that being justified by his grace we might become heirs according to the hope of eternal life."]]},"Titus 3:5-7":{"b":"Titus","v":[[3,5,"he saved us, not because of works done by us in righteousness, but according to his own mercy, by the washing of regeneration and renewal of the Holy Spirit,"],[3,6,"whom he poured out on us richly through Jesus Christ our Savior,"],[3,7,"so that being justified by his grace we might become heirs according to the hope of eternal life."]]}};
